 "content": "from collections import deque


def transform(grid):
    """Pack each 4-connected nonzero object as far right as possible."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w
                            and p not in seen and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        cells.add(p)
                        q.append(p)
            objects.append((color, cells))

    # Repeatedly slide objects right. Repetition lets an object move again
    # after the object ahead of it has itself advanced.
    moved = True
    while moved:
        moved = False
        for i, (color, cells) in enumerate(objects):
            occupied_by_others = set()
            for j, (_, other_cells) in enumerate(objects):
                if i != j:
                    occupied_by_others.update(other_cells)
            if all(c + 1 < w and (r, c + 1) not in occupied_by_others
                   for r, c in cells):
                objects[i] = (color, {(r, c + 1) for r, c in cells})
                moved = True

    out = [[0] * w for _ in range(h)]
    for color, cells in objects:
        for r, c in cells:
            out[r][c] = color
    return out


